static const float DebugScale = 1.0;
/// @sort 32
uniform float Strength = 1.0;
/// @sort 32
uniform float2 Offset = float2(0.25, 0.75);
/// @sort 32
uniform float3 Tint = float3(1.0, 1.0, 1.0);
/// @sort 32
uniform float4 Full = float4(0.1, 0.2, 0.3, 0.4);
// Compact spellings: a type and a default are a uniform; `const` is a `static const`.
/// @name M_LpCompact
export void M_LpCompact(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    Color = Tint * Strength * DebugScale + float3(Offset.x, Offset.y, Full.a);
    Base.EmissiveColor = Color;
}
